/* the captured half of an Atomics operation: the length ValidateAtomicAccess reads at step 1, held across the
   index's own coercion, plus the argument vector the body will read. */
typedef struct JSAtomics {
    JSStepHdr hdr;        /* MUST be first: the generic step driver casts the state to JSStepHdr * */
    JSValue result;       /* DONE (owned) */
    JSValue *argp;        /* the arguments, each coerced one replaced in place (owned) */
    int nargp;
    uint32_t length;      /* TypedArrayLength, read BEFORE the index was coerced */
    int i;                /* the coercion cursor */
    JSValue cb[1];        /* the TOPRIMITIVE request buffer */
    JSValue wait_rec;     /* Atomics.wait's Waiter Record while its agent is suspended on it (owned) */
} JSAtomics;

/* the captured half of a Date setter: everything read at step 2, held across the argument coercions. */
typedef struct JSDateSet {
    JSStepHdr hdr;        /* MUST be first: the generic step driver casts the state to JSStepHdr * */
    JSValue result;       /* DONE (owned) */
    double fields[9];     /* derived from the [[DateValue]] read BEFORE any argument was coerced */
    int res;              /* get_date_fields' answer: 0 = the stored time value was NaN */
    int i, n;             /* the coercion cursor and how many arguments the spec names */
    bool nonfinite;       /* an argument coerced to an infinity or a NaN */
} JSDateSet;
static const JSTrampStepDef js_date_ctor_def = { sizeof(JSDateCtor), js_date_ctor_step, js_date_ctor_fini, 0, .visit = js_date_ctor_visit,
                   .algorithm = "21.4.2.1 Date ( ...values )",
                   .steps = js_date_ctor_steps };
/* An OrdinaryCreateFromConstructor declaration: the CLASS and the body's DECLARED ARGUMENT COUNT in `arg`, the
   post-create body (NULL = the object is the result), and the same precheck hook the coerce-then-compute machines
   use for a leading validation. The count is part of the declaration for the same reason PRIMARGS carries its
   own: js_call_c_function pads a C body's vector to its declared length and a machine gets the call's real
   operands, so a body that reads argv[1] of a zero-argument call needs the padding built here. */
static const char *const js_creatector_steps[];
#define CREATECTOR_DEF_FULL(class_id, nargs, proto, fn, magic, pre) \
    { sizeof(JSCreateCtor), js_creatector_step, js_creatector_fini, CREATECTOR_ARG(class_id, nargs), \
      { .proto = (fn) }, JS_CFUNC_##proto, (magic), (pre), NULL, NULL, .visit = js_creatector_visit, \
      .algorithm = "10.1.13 OrdinaryCreateFromConstructor", .steps = js_creatector_steps }
#define CREATECTOR_DEF(class_id, nargs, proto, fn, magic) \
    CREATECTOR_DEF_FULL(class_id, nargs, proto, fn, magic, NULL)
